let cachedIcd9Map: Map<string, Icd9ServiceMapping> | null = null;

export function getIcd9LookupMap(
  customList?: Icd9ServiceMapping[],
): Map<string, Icd9ServiceMapping> {
  if (customList && customList.length > 0) {
    const map = new Map<string, Icd9ServiceMapping>();
    for (const item of customList) {
      if (item.maDichVu && !map.has(item.maDichVu.trim())) {
        map.set(item.maDichVu.trim(), item);
      }
    }
    return map;
  }
  if (!cachedIcd9Map) {
    cachedIcd9Map = new Map<string, Icd9ServiceMapping>();
    for (const item of DEFAULT_ICD9_CM_SERVICES) {
      if (item.maDichVu && !cachedIcd9Map.has(item.maDichVu.trim())) {
        cachedIcd9Map.set(item.maDichVu.trim(), item);
      }
    }
  }
  return cachedIcd9Map;
}

export function findIcd9Mapping(
  maDichVu: string | undefined | null,
  customList?: Icd9ServiceMapping[],
): Icd9ServiceMapping | undefined {
  if (!maDichVu) return undefined;
  const cleanCode = maDichVu.trim();
  const map = getIcd9LookupMap(customList);
  return map.get(cleanCode);
}

export function loadIcd9Services(): Icd9ServiceMapping[] {
  try {
    const raw = localStorage.getItem(ICD9_SERVICES_STORAGE_KEY);
    if (!raw) return DEFAULT_ICD9_CM_SERVICES;
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed) && parsed.length > 0) {
      return parsed;
    }
    return DEFAULT_ICD9_CM_SERVICES;
  } catch {
    return DEFAULT_ICD9_CM_SERVICES;
  }
}

export function saveIcd9Services(list: Icd9ServiceMapping[]): void {
  try {
    localStorage.setItem(ICD9_SERVICES_STORAGE_KEY, JSON.stringify(list));
    cachedIcd9Map = null;
  } catch (err) {
    console.error("Lỗi khi lưu danh mục ICD9-CM:", err);
  }
}

export function resetIcd9Services(): Icd9ServiceMapping[] {
  localStorage.removeItem(ICD9_SERVICES_STORAGE_KEY);
  cachedIcd9Map = null;
  return DEFAULT_ICD9_CM_SERVICES;
}
